validator:
function validate(input) {
  const [{ Product = [], Sales = [] }] = input;
  const products = new Set();
  for (const row of Product) {
    if (row.some((v) => v === null)) return 'Product rows may not contain null.';
    if (products.has(row[0])) return `product_id ${row[0]} appears twice in Product.`;
    if (row[2] < 0) return `Product ${row[0]} has a negative unit_price.`;
    products.add(row[0]);
  }
  for (const row of Sales) {
    if (row.some((v) => v === null)) return 'Sales rows may not contain null.';
    if (!products.has(row[1])) return `A sale names unknown product ${row[1]}.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(row[3])) return `sale_date ${row[3]} is not a YYYY-MM-DD date.`;
    if (row[4] < 1) return 'quantity must be at least 1.';
    if (row[5] < 0) return 'price may not be negative.';
  }
  return null;
}

