function generate(rand, size) {
  const small = size === 'small';
  const names = ['S8', 'G4', 'iPhone', 'Pixel', 'Note', 'Mi'];
  const Product = [];
  const productCount = small ? 1 + Math.floor(rand() * 3) : 50;
  for (let id = 1; id <= productCount; id++) {
    const unit = small ? [400, 800, 1000, 1400][Math.floor(rand() * 4)] : 100 * (1 + Math.floor(rand() * 20));
    Product.push([id, names[(id - 1) % names.length] + (small ? '' : String(id)), unit]);
  }
  const Sales = [];
  const rows = small ? Math.floor(rand() * 9) : 2000;
  const sellers = small ? 3 : 200;
  for (let i = 0; i < rows; i++) {
    // Small cases sometimes repeat the previous sale verbatim, since identical rows are allowed.
    if (small && Sales.length > 0 && rand() < 0.2) { Sales.push(Sales[Sales.length - 1].slice()); continue; }
    const [productId, , unit] = Product[Math.floor(rand() * Product.length)];
    const quantity = 1 + Math.floor(rand() * (small ? 2 : 5));
    const month = 1 + Math.floor(rand() * 12), day = 1 + Math.floor(rand() * 28);
    const date = `2019-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    Sales.push([1 + Math.floor(rand() * sellers), productId, 1 + Math.floor(rand() * (small ? 4 : 500)), date, quantity, quantity * unit]);
  }
  return [{ Product, Sales }];
}
